class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frames = []
        self.current = []

    def _game_complete(self):
        return len(self.frames) == 10

    def _frame_complete(self, frame_index, current):
        n = len(current)
        if frame_index < 9:
            if n == 1 and current[0] == 10:
                return True
            return n == 2
        # Tenth frame
        if n == 1:
            return False
        if n == 2:
            # Strike or spare earns a bonus roll (or two).
            if current[0] == 10 or current[0] + current[1] == 10:
                return False
            return True
        return n == 3

    def roll(self, pins):
        if self._game_complete():
            raise Exception("Cannot roll if game already has ten frames")
        if pins < 0 or pins > 10:
            raise Exception("A roll cannot score negative or more than 10 points")

        frame_index = len(self.frames)
        current = self.current
        n = len(current)

        if frame_index < 9:
            if n == 1 and current[0] + pins > 10:
                raise Exception("Two rolls in a frame cannot score more than 10 points")
        else:
            if n == 1 and current[0] < 10 and current[0] + pins > 10:
                raise Exception("Two rolls in a frame cannot score more than 10 points")
            if n == 2 and current[1] < 10 and current[1] + pins > 10:
                raise Exception("Two bonus rolls cannot score more than 10 points")

        self.rolls.append(pins)
        current.append(pins)

        if self._frame_complete(frame_index, current):
            self.frames.append(current)
            self.current = []

    def score(self):
        if not self._game_complete():
            raise Exception("Cannot score an incomplete game")

        total = 0
        i = 0
        rolls = self.rolls
        for _ in range(10):
            if rolls[i] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                total += 10 + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total

